package io.knowledgebrain.learning;
import java.util.*;
import java.io.IOException;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.MeterRegistry;

@RestController
@ConditionalOnProperty(name="brain.learning.public.enabled",havingValue="true")
@RequestMapping("/api/public/spaces/{spaceId}")
final class PublicRoadmapController {
 private final PublicRoadmapStore store;private final SpaceAuthorizationClient authority;private final RoadmapController browser;private final MeterRegistry metrics;private final String origin;
 PublicRoadmapController(PublicRoadmapStore store,SpaceAuthorizationClient authority,RoadmapController browser,MeterRegistry metrics,@Value("${brain.learning.browser-origin}")String origin){this.store=store;this.authority=authority;this.browser=browser;this.metrics=metrics;this.origin=origin;}
 UUID authorize(UUID space,HttpServletRequest r,String action,String trace){if(!r.isSecure())throw RoadmapGraph.bad();if(!action.equals("PUBLIC_ROADMAP_READ")&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Duplicate credential");token=c.getValue();}return authority.authorize(space,token,action,"PUBLIC",trace);}
 private static ResponseEntity<?> ok(Object v){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(v);}
 private static ResponseEntity<?> proposal(PublicRoadmapStore.Proposal p,int status){return ResponseEntity.status(status).cacheControl(CacheControl.noStore()).eTag("\"pc"+p.version()+"\"").body(p);}
 private static long expected(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(h.size()!=1||!h.getFirst().matches("\"pc[1-9][0-9]{0,18}\""))throw RoadmapGraph.bad();try{return Long.parseLong(h.getFirst().substring(3,h.getFirst().length()-1));}catch(NumberFormatException e){throw RoadmapGraph.bad();}}
 private static void shape(tools.jackson.databind.JsonNode v,Set<String> fields){if(v.size()!=fields.size()||fields.stream().anyMatch(f->!v.has(f)))throw RoadmapGraph.bad();}
 private static String text(tools.jackson.databind.JsonNode v,String key){if(!v.path(key).isString())throw RoadmapGraph.bad();return v.path(key).asString();}
 private UUID cursor(HttpServletRequest r){return r.getParameter("after")==null?null:RoadmapGraph.id(r.getParameter("after"));}
 private int limit(HttpServletRequest r){return (int)RoadmapController.number(r.getParameter("limit"),20,100);}
 @GetMapping("/roadmaps") ResponseEntity<?> list(@PathVariable String spaceId,HttpServletRequest r){RoadmapController.parameters(r,Set.of("after","limit"));var space=RoadmapGraph.id(spaceId);UUID after=cursor(r);int limit=limit(r);authorize(space,r,"PUBLIC_ROADMAP_READ",RoadmapController.parent(r));metrics.counter("brain.learning.public.reads","type","catalog").increment();return ok(store.list(space,after,limit));}
 @GetMapping("/roadmaps/{roadmapId}") ResponseEntity<?> get(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);authorize(space,r,"PUBLIC_ROADMAP_READ",RoadmapController.parent(r));var v=store.get(space,id);metrics.counter("brain.learning.public.reads","type","current").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"rmp"+v.version()+"\"").body(v);}
 @GetMapping("/roadmaps/{roadmapId}/revisions") ResponseEntity<?> history(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){RoadmapController.parameters(r,Set.of("before","limit"));var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);long before=RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)RoadmapController.number(r.getParameter("limit"),5,10);authorize(space,r,"PUBLIC_ROADMAP_READ",RoadmapController.parent(r));return ok(store.history(space,id,before,limit));}
 @GetMapping("/roadmap-contributions") ResponseEntity<?> proposals(@PathVariable String spaceId,HttpServletRequest r){RoadmapController.parameters(r,Set.of("after","limit"));var space=RoadmapGraph.id(spaceId);UUID after=cursor(r);int limit=limit(r);authorize(space,r,"PUBLIC_ROADMAP_READ",RoadmapController.parent(r));return ok(store.proposals(space,after,limit));}
 @GetMapping("/roadmap-contributions/{contributionId}") ResponseEntity<?> proposal(@PathVariable String spaceId,@PathVariable String contributionId,HttpServletRequest r){RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(contributionId);authorize(space,r,"PUBLIC_ROADMAP_READ",RoadmapController.parent(r));return proposal(store.proposal(space,id),200);}
 @GetMapping("/roadmap-contributions/{contributionId}/reviews") ResponseEntity<?> reviews(@PathVariable String spaceId,@PathVariable String contributionId,HttpServletRequest r){RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(contributionId);authorize(space,r,"PUBLIC_ROADMAP_READ",RoadmapController.parent(r));return ok(store.reviews(space,id));}
 @PostMapping("/roadmap-contributions") ResponseEntity<?> submit(@PathVariable String spaceId,HttpServletRequest r)throws IOException{RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);String trace=RoadmapController.parent(r);UUID actor=authorize(space,r,"ROADMAP_PROPOSE",trace);var v=browser.body(r,1048576);shape(v,Set.of("roadmapId","baseVersion","title","description","rationale","nodes","edges"));var b=v.path("baseVersion");if(!b.isIntegralNumber()||!b.canConvertToLong())throw RoadmapGraph.bad();UUID target=v.path("roadmapId").isNull()?null:RoadmapGraph.id(text(v,"roadmapId"));var graph=parseGraph(v);var p=store.submit(space,actor,target,b.asLong(),text(v,"title"),text(v,"description"),text(v,"rationale"),graph,trace.substring(3,35));changed("submitted",p,trace);return proposal(p,201);}
 private RoadmapGraph.Edit parseGraph(tools.jackson.databind.JsonNode v){if(!v.path("nodes").isArray()||!v.path("edges").isArray()||v.path("nodes").size()>100||v.path("edges").size()>500)throw RoadmapGraph.bad();var nodes=new ArrayList<RoadmapGraph.NodeEdit>();var edges=new ArrayList<RoadmapGraph.EdgeEdit>();for(var n:v.path("nodes")){if(!n.isObject())throw RoadmapGraph.bad();shape(n,Set.of("key","title","description"));nodes.add(new RoadmapGraph.NodeEdit(text(n,"key"),text(n,"title"),text(n,"description")));}for(var e:v.path("edges")){if(!e.isObject())throw RoadmapGraph.bad();shape(e,Set.of("key","kind","source","target"));edges.add(new RoadmapGraph.EdgeEdit(text(e,"key"),text(e,"kind"),text(e,"source"),text(e,"target")));}return new RoadmapGraph.Edit(nodes,edges);}
 @PostMapping("/roadmap-contributions/{contributionId}/review") ResponseEntity<?> review(@PathVariable String spaceId,@PathVariable String contributionId,HttpServletRequest r)throws IOException{RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(contributionId);String trace=RoadmapController.parent(r);UUID actor=authorize(space,r,"ROADMAP_REVIEW",trace);long version=expected(r);var v=browser.body(r,32768);shape(v,Set.of("decision","reason"));var p=store.review(space,id,actor,version,text(v,"decision"),text(v,"reason"),trace.substring(3,35));changed("reviewed",p,trace);return proposal(p,200);}
 @PostMapping("/roadmap-contributions/{contributionId}/merge") ResponseEntity<?> merge(@PathVariable String spaceId,@PathVariable String contributionId,HttpServletRequest r)throws IOException{RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(contributionId);String trace=RoadmapController.parent(r);UUID actor=authorize(space,r,"ROADMAP_MERGE",trace);long version=expected(r);shape(browser.body(r,32768),Set.of());var p=store.merge(space,id,actor,version,trace.substring(3,35));changed("merged",p,trace);return proposal(p,200);}
 private void changed(String type,PublicRoadmapStore.Proposal p,String trace){metrics.counter("brain.learning.public.changes","type",type).increment();org.slf4j.LoggerFactory.getLogger(getClass()).info("public_roadmap_contribution state={} contribution_id={} trace_id={}",p.state(),p.contributionId(),trace.substring(3,35));}
}
